//! Layout tests via i-slint-backend-testing. Requires the Slint compiler's
//! debug info (enabled in build.rs) so elements can be located and measured.
//!
//! Icon centering: every IconButton's icon image must share its container's
//! center (within 1 px) at ui-scales 1.0 / 1.5 / 2.0.
//! Poster geometry: poster boxes must not change with title length.
//! Parental controls: the PIN dialog, age picker and kid badge fixtures
//! mount/unmount behind their `test-*` properties in the TestWindow.

use i_slint_backend_testing::ElementQuery;

// The UI is generated by this package's build script; the generated TestWindow
// is only used by these tests (main.rs uses MainWindow).
slint::include_modules!();

const TOL: f32 = 1.0;

fn centers(handle: &i_slint_backend_testing::ElementHandle) -> (f32, f32, f32, f32) {
    let pos = handle.absolute_position();
    let size = handle.size();
    (pos.x, pos.y, size.width, size.height)
}

#[test]
fn icon_button_centers_icon_at_all_scales() {
    i_slint_backend_testing::init_no_event_loop();
    let win = TestWindow::new().unwrap();
    for scale in [1.0f32, 1.5, 2.0] {
        win.set_scale(scale);
        // Icon-only buttons: icon center == container center.
        for id in ["btn-gear", "btn-close"] {
            let b = ElementQuery::from_root(&win)
                .match_id(format!("TestWindow::{id}"))
                .find_first()
                .unwrap_or_else(|| panic!("scale {scale}: missing {id}"));
            let icon = b
                .query_descendants()
                .match_type_name("Image")
                .find_first()
                .unwrap_or_else(|| panic!("scale {scale}: {id} has no icon image"));
            let (bx, by, bw, bh) = centers(&b);
            let (ix, iy, iw, ih) = centers(&icon);
            let dx = (ix + iw / 2.0) - (bx + bw / 2.0);
            let dy = (iy + ih / 2.0) - (by + bh / 2.0);
            assert!(
                dx.abs() <= TOL && dy.abs() <= TOL,
                "scale {scale}: {id} icon off-center by ({dx:.2}, {dy:.2}) px",
            );
        }
        // Labeled button: the icon+text group is centered, i.e. the midpoint
        // of (icon left edge, text right edge) equals the container center.
        let b = ElementQuery::from_root(&win)
            .match_id("TestWindow::btn-labeled")
            .find_first()
            .expect("btn-labeled");
        let icon = b
            .query_descendants()
            .match_type_name("Image")
            .find_first()
            .expect("btn-labeled icon");
        let text = b
            .query_descendants()
            .match_type_name("Text")
            .find_first()
            .expect("btn-labeled text");
        let (bx, by, bw, bh) = centers(&b);
        let (ix, iy, _, ih) = centers(&icon);
        let (tx, _, tw, _) = centers(&text);
        let dx = (ix + tx + tw) / 2.0 - (bx + bw / 2.0);
        let dy = iy + ih / 2.0 - (by + bh / 2.0);
        assert!(
            dx.abs() <= TOL && dy.abs() <= TOL,
            "scale {scale}: btn-labeled group off-center by ({dx:.2}, {dy:.2}) px",
        );
    }
}

#[test]
fn poster_geometry_independent_of_title_length() {
    i_slint_backend_testing::init_no_event_loop();
    let win = TestWindow::new().unwrap();
    for scale in [1.0f32, 1.5, 2.0] {
        win.set_scale(scale);
        let mut reference: Option<(f32, f32)> = None;
        for id in ["card-short", "card-40", "card-120", "card-noposter"] {
            let card = ElementQuery::from_root(&win)
                .match_id(format!("TestWindow::{id}"))
                .find_first()
                .unwrap_or_else(|| panic!("scale {scale}: missing {id}"));
            // The poster image inside the card (absent for card-noposter;
            // compare the card's own geometry there via the image holder).
            let (w, h) = {
                let s = card.size();
                (s.width, s.height)
            };
            match reference {
                None => reference = Some((w, h)),
                Some((rw, rh)) => assert!(
                    (w - rw).abs() <= TOL && (h - rh).abs() <= TOL,
                    "scale {scale}: {id} is {w}x{h}, first card is {rw}x{rh}",
                ),
            }
            // The poster box must keep the 2:3 aspect (height = width * 1.5).
            let poster = card
                .query_descendants()
                .match_id("PosterCard::card")
                .find_first()
                .expect("poster box");
            let ps = poster.size();
            assert!(
                (ps.height - ps.width * 1.5).abs() <= TOL,
                "scale {scale}: {id} poster box {}x{} not 2:3",
                ps.width,
                ps.height,
            );
        }
    }
}

// Parental-controls fixtures (see the TestWindow harness at the bottom of
// ui/main.slint): the `test-*` properties flip the same conditional
// elements the real overlay state drives.

#[test]
fn pin_dialog_opens_and_closes() {
    i_slint_backend_testing::init_no_event_loop();
    let win = TestWindow::new().unwrap();
    // Closed: the conditional dialog is not instantiated at all.
    assert!(
        ElementQuery::from_root(&win)
            .match_id("TestWindow::pin-dialog-test")
            .find_first()
            .is_none(),
        "pin dialog must start closed",
    );
    // Open: the dialog exists and centers a non-empty panel.
    win.set_test_pin_open(true);
    let dlg = ElementQuery::from_root(&win)
        .match_id("TestWindow::pin-dialog-test")
        .find_first()
        .expect("pin dialog opens");
    let panel = dlg
        .query_descendants()
        .match_id("PinDialog::panel")
        .find_first()
        .expect("pin dialog panel");
    let (_, _, dw, dh) = centers(&dlg);
    let (px, py, pw, ph) = centers(&panel);
    assert!(pw > 0.0 && ph > 0.0, "pin panel is empty ({pw}x{ph})");
    let dx = px + pw / 2.0 - dw / 2.0;
    let dy = py + ph / 2.0 - dh / 2.0;
    assert!(
        dx.abs() <= TOL && dy.abs() <= TOL,
        "pin panel off-center by ({dx:.2}, {dy:.2}) px",
    );
    // Closed again: the conditional element is torn back down.
    win.set_test_pin_open(false);
    assert!(
        ElementQuery::from_root(&win)
            .match_id("TestWindow::pin-dialog-test")
            .find_first()
            .is_none(),
        "pin dialog must close",
    );
}

#[test]
fn age_picker_shows_for_child_kind() {
    i_slint_backend_testing::init_no_event_loop();
    let win = TestWindow::new().unwrap();
    // Adult kind: no age row.
    assert!(
        ElementQuery::from_root(&win)
            .match_id("TestWindow::age-picker-test")
            .find_first()
            .is_none(),
        "age picker must start hidden for adult kind",
    );
    // Child kind: the picker mounts, two-way bound to `test-age`.
    win.set_test_child(true);
    let picker = ElementQuery::from_root(&win)
        .match_id("TestWindow::age-picker-test")
        .find_first()
        .expect("age picker shows for child kind");
    let (_, _, pw, ph) = centers(&picker);
    assert!(pw > 0.0 && ph > 0.0, "age picker is empty ({pw}x{ph})");
    // Back to adult kind: unmounted again.
    win.set_test_child(false);
    assert!(
        ElementQuery::from_root(&win)
            .match_id("TestWindow::age-picker-test")
            .find_first()
            .is_none(),
        "age picker must hide for adult kind",
    );
}

#[test]
fn child_badge_marks_child_tiles() {
    i_slint_backend_testing::init_no_event_loop();
    let win = TestWindow::new().unwrap();
    // Adult tile: no badge.
    assert!(
        ElementQuery::from_root(&win)
            .match_id("TestWindow::child-badge-test")
            .find_first()
            .is_none(),
        "kid badge must start hidden for adult kind",
    );
    // Child tile: the badge mounts at its fixture spot (200, 620), 22 px
    // tall at ui-scale 1.0 (KidBadge height = 22px * Theme.scale).
    win.set_test_child(true);
    let badge = ElementQuery::from_root(&win)
        .match_id("TestWindow::child-badge-test")
        .find_first()
        .expect("kid badge shows for child kind");
    let (bx, by, bw, bh) = centers(&badge);
    assert!(
        (bx - 200.0).abs() <= TOL && (by - 620.0).abs() <= TOL,
        "kid badge at ({bx:.2}, {by:.2}), expected (200, 620)",
    );
    assert!(
        bw > 0.0 && (bh - 22.0).abs() <= TOL,
        "kid badge is {bw:.2}x{bh:.2}, expected a nonzero width and 22 px height",
    );
    // Back to adult kind: gone again.
    win.set_test_child(false);
    assert!(
        ElementQuery::from_root(&win)
            .match_id("TestWindow::child-badge-test")
            .find_first()
            .is_none(),
        "kid badge must hide for adult kind",
    );
}
